17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.Objects;
26	import java.util.stream.Collectors;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.security.core.Authentication;
34	import org.springframework.security.core.context.SecurityContextHolder;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Dedicated audit logger recording successful owner creations.
68	     */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
120	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        if (hasReachedCityCapacity(owner.getCity())) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
133	        owner.setSharesHousehold(sharesHousehold(owner));
134	        owner.setLocality(determineLocality(owner.getCity()));
135	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
136	        owner.setMembershipTier(determineMembershipTier(owner.getMembershipNumber()));
137	        owner.setCity(normalizeCity(owner.getCity()));
138	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
139	        long areaCodeMatches = countOwnersSharingAreaCode(owner.getTelephone());
140	        this.clinicService.saveOwner(owner);
141	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
142	            currentUsername(), owner.getId(), owner.getMembershipNumber());
143	        if (areaCodeMatches >= BULK_SIGNUP_AREA_CODE_THRESHOLD) {
144	            AUDIT.warn("Possible bulk signup: owner ownerId={} telephone area code={} shared with {} existing owners",
145	                owner.getId(), areaCode(owner.getTelephone()), areaCodeMatches);
146	        }
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
152	
153	    /**
154	     * The number of existing owners that must share a newly created owner's telephone area code
155	     * (the first three digits) before the creation is flagged as a possible bulk signup.
156	     */
157	    private static final long BULK_SIGNUP_AREA_CODE_THRESHOLD = 5;
158	
159	    /**
160	     * Extracts the area code, i.e. the first three digits, of a normalized telephone number.
161	     * Returns {@code null} when the telephone is absent or has fewer than three digits.
162	     */
163	    private static String areaCode(String telephone) {
164	        if (telephone == null || telephone.length() < 3) {
165	            return null;
166	        }
167	        return telephone.substring(0, 3);
168	    }
169	
170	    /**
171	     * Counts how many existing owners share the given telephone's area code (its first three
172	     * digits). The newly created owner itself is not yet persisted and so is never included in
173	     * the count. When the telephone has no determinable area code, no owner is matched.
174	     */
175	    private long countOwnersSharingAreaCode(String telephone) {
176	        String areaCode = areaCode(telephone);
177	        if (areaCode == null) {
178	            return 0;
179	        }
180	        return this.clinicService.findAllOwners().stream()
181	            .filter(existing -> Objects.equals(areaCode(normalizeTelephone(existing.getTelephone())), areaCode))
182	            .count();
183	    }
184	
185	    /**
186	     * Returns the name of the currently authenticated user, or {@code "anonymous"}
187	     * when no authentication is present in the security context.
188	     */
189	    private static String currentUsername() {
190	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
191	        return authentication != null ? authentication.getName() : "anonymous";
192	    }
193	
194	    /**
195	     * The maximum number of owners that may be registered on any single day.
196	     */
197	    private static final long MAX_OWNERS_PER_DAY = 20;
198	
199	    /**
200	     * Determines whether the number of owners already registered on the given date has reached the
201	     * daily registration limit. When 20 owners share the same registration date, no further owner may
202	     * be created for that day.
203	     */
204	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
205	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
206	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
207	            .count();
208	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
209	    }
210	
211	    /**
212	     * The maximum number of owners that may share a single city.
213	     */
214	    private static final long MAX_OWNERS_PER_CITY = 8;
215	
216	    /**
217	     * Determines whether the given city has already reached its capacity of owners. When a city
218	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
219	     * ignoring letter case.
220	     */
221	    private boolean hasReachedCityCapacity(String city) {
222	        if (city == null) {
223	            return false;
224	        }
225	        long ownersInCity = this.clinicService.findAllOwners().stream()
226	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
227	            .count();
228	        return ownersInCity >= MAX_OWNERS_PER_CITY;
229	    }
230	
231	    /**
232	     * Counts how many existing owners share the given last name at the moment a new owner is
233	     * created. The newly created owner itself is not yet persisted and so is never included in
234	     * the count. Last names are compared exactly.
235	     */
236	    private int countNamesakes(String lastName) {
237	        if (lastName == null) {
238	            return 0;
239	        }
240	        return (int) this.clinicService.findAllOwners().stream()
241	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
242	            .count();
243	    }
244	
245	    /**
246	     * Determines whether the given owner shares a household with an owner that already exists,
247	     * meaning another owner already has the same address and city. Addresses and cities are
248	     * compared ignoring letter case and any surrounding or repeated whitespace. The newly created
249	     * owner itself is not yet persisted and so is never matched against.
250	     */
251	    private boolean sharesHousehold(Owner owner) {
252	        String address = normalize(owner.getAddress());
253	        String city = normalize(owner.getCity());
254	        if (address == null || city == null) {
255	            return false;
256	        }
257	        return this.clinicService.findAllOwners().stream()
258	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
259	                && Objects.equals(normalize(existing.getCity()), city));
260	    }
261	
262	    /**
263	     * Determines the locality of a newly created owner based on its city. The owner is 'local'
264	     * when its city is the single most common city among the owners that already exist at the
265	     * moment of creation; otherwise it is 'remote'. When no city is the sole most common one
266	     * (for example because two cities are tied for the highest count, or no owners yet exist),
267	     * every newly created owner is 'remote'. Cities are compared ignoring letter case.
268	     */
269	    private String determineLocality(String city) {
270	        if (city == null) {
271	            return "REMOTE";
272	        }
273	        Map<String, Long> cityCounts = this.clinicService.findAllOwners().stream()
274	            .map(Owner::getCity)
275	            .filter(existing -> existing != null)
276	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT), Collectors.counting()));
277	        if (cityCounts.isEmpty()) {
278	            return "REMOTE";
279	        }
280	        long maxCount = Collections.max(cityCounts.values());
281	        List<String> mostCommonCities = cityCounts.entrySet().stream()
282	            .filter(entry -> entry.getValue() == maxCount)
283	            .map(Map.Entry::getKey)
284	            .toList();
285	        if (mostCommonCities.size() != 1) {
286	            return "REMOTE";
287	        }
288	        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "LOCAL" : "REMOTE";
289	    }
290	
291	    /**
292	     * The number of owners that receive the founding membership tier. The first 100 owners ever
293	     * created are 'FOUNDING'; every owner created thereafter is 'STANDARD'.
294	     */
295	    private static final int FOUNDING_TIER_LIMIT = 100;
296	
297	    /**
298	     * Determines the membership tier for a newly created owner based on its sequential membership
299	     * number. Owners whose membership number is within the first {@value #FOUNDING_TIER_LIMIT} are
300	     * 'FOUNDING'; all later owners are 'STANDARD'.
301	     */
302	    private String determineMembershipTier(int membershipNumber) {
303	        return membershipNumber <= FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
304	    }
305	
306	    /**
307	     * Generates the customer code for a newly created owner. The code is formatted as
308	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
309	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
310	     * Cities are matched ignoring letter case.
311	     */
312	    private String generateCustomerCode(String city) {
313	        long ownersInCity = this.clinicService.findAllOwners().stream()
314	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
315	            .count();
316	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
317	    }
318	
319	    /**
320	     * Normalizes the city of a newly created owner. If an owner already exists in the same
321	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
322	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
323	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
324	     * lowercasing the rest, so for example "new york" becomes "New York".
325	     */
326	    private String normalizeCity(String city) {
327	        if (city == null) {
328	            return null;
329	        }
330	        return this.clinicService.findAllOwners().stream()
331	            .map(Owner::getCity)
332	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
333	            .findFirst()
334	            .orElseGet(() -> toTitleCase(city));
335	    }
336	
337	    /**
338	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
339	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
340	     * "new  YORK" becomes "New  York".
341	     */
342	    private static String toTitleCase(String value) {
343	        StringBuilder result = new StringBuilder(value.length());
344	        boolean capitalizeNext = true;
345	        for (int i = 0; i < value.length(); i++) {
346	            char c = value.charAt(i);
347	            if (Character.isWhitespace(c)) {
348	                capitalizeNext = true;
349	                result.append(c);
350	            } else if (capitalizeNext) {
351	                result.append(Character.toTitleCase(c));
352	                capitalizeNext = false;
353	            } else {
354	                result.append(Character.toLowerCase(c));
355	            }
356	        }
357	        return result.toString();
358	    }
359	
360	    /**
361	     * Determines whether an owner already exists that uses the same telephone number
362	     * as the given one. Telephone numbers must be unique across all owners. The
363	     * comparison ignores letter case and any surrounding or repeated whitespace.
364	     */
365	    private boolean isDuplicateOwner(Owner owner) {
366	        String telephone = normalizeTelephone(owner.getTelephone());
367	        return this.clinicService.findAllOwners().stream()
368	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
369	    }
370	
371	    /**
372	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
373	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
374	     * "6135550100". This lets differently punctuated forms of the same number be treated as
375	     * equal for the uniqueness check and stored in a single canonical form.
376	     */
377	    private static String normalizeTelephone(String telephone) {
378	        if (telephone == null) {
379	            return null;
380	        }
381	        return telephone.replaceAll("[\\s()-]", "");
382	    }
383	
384	    /**
385	     * Determines whether another owner already uses the same email address as the given one.
386	     * Email addresses, when supplied, must be unique across all owners. An owner without an
387	     * email address is never considered a duplicate. The comparison ignores letter case and
388	     * any surrounding or repeated whitespace.
389	     */
390	    private boolean isDuplicateEmail(Owner owner) {
391	        String email = normalize(owner.getEmail());
392	        if (email == null || email.isEmpty()) {
393	            return false;
394	        }
395	        return this.clinicService.findAllOwners().stream()
396	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
397	    }
398	
399	    /**
400	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
401	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
402	     * and "John Smith" normalize to the same key and so count as the same person.
403	     */
404	    private static String normalize(String value) {
405	        if (value == null) {
406	            return null;
407	        }
408	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
414	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
415	        if (currentOwner == null) {
416	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
417	        }
418	        currentOwner.setAddress(ownerFieldsDto.getAddress());
419	        currentOwner.setCity(ownerFieldsDto.getCity());
420	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
421	        currentOwner.setLastName(ownerFieldsDto.getLastName());
422	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
423	        this.clinicService.saveOwner(currentOwner);
424	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
425	    }
426	
427	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
428	    @Transactional
429	    @Override
430	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
431	        Owner owner = this.clinicService.findOwnerById(ownerId);
432	        if (owner == null) {
433	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
434	        }
435	        this.clinicService.deleteOwner(owner);
436	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
437	    }
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Override
441	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner == null) {
444	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	        }
446	        HttpHeaders headers = new HttpHeaders();
447	        Pet pet = petMapper.toPet(petFieldsDto);
448	        owner.setId(ownerId);
449	        pet.setOwner(owner);
450	        pet.getType().setName(null);
451	        this.clinicService.savePet(pet);
452	        PetDto petDto = petMapper.toPetDto(pet);
453	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
454	            .buildAndExpand(pet.getId()).toUri());
455	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
456	    }
457	
458	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
459	    @Override
460	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
461	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
462	        if (currentOwner != null) {
463	            Pet currentPet = this.clinicService.findPetById(petId);
464	            if (currentPet != null) {
465	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
466	                currentPet.setName(petFieldsDto.getName());
467	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
468	                this.clinicService.savePet(currentPet);
469	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
470	            }
471	        }
472	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
473	    }
474	
475	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
476	    @Override
477	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
478	        HttpHeaders headers = new HttpHeaders();
479	        Visit visit = visitMapper.toVisit(visitFieldsDto);
480	        Pet pet = new Pet();
481	        pet.setId(petId);
482	        visit.setPet(pet);
483	        this.clinicService.saveVisit(visit);
484	        VisitDto visitDto = visitMapper.toVisitDto(visit);
485	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
486	            .buildAndExpand(visit.getId()).toUri());
487	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
488	    }
489	
490	
491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
494	        Owner owner = this.clinicService.findOwnerById(ownerId);
495	        if (owner != null) {
496	            Pet pet = owner.getPet(petId);
497	            if (pet != null) {
498	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
499	            }
500	        }
501	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
502	    }
503	}
